    "turkish": "Adama mal bulmak kolay ama adama adam bulmak zor.",
    "comment": "Hazreti Ömer r.a. bir gün dostları ile otururken: “Haydi, herkes Allah’tan bir dilekte bulunsun” demiş. Onlar, “Allah yolunda harcamak için mal, mülk ve altın” dilemişler.” Hz. Ömer ise, “ben, Ebu Ubeyde bin Cerrah, Muaz bin Cebel ve Huzeyfe bin Yeman gibilerden şu oda dolusu insan isterim ki onları, Allah yolunda görevlendirebileyim.” demiş. (Kandehlevi, 125; Buhari, et-Tarihu’l-Avsat, 54)",
