    "comment": "Ecel birdir, değişmez. Herkes, er ya da geç, öyle ya da böyle, ölür. Adır kelimesi Kırgız ve Kazakçada tepe, otlak yer anlamına gelir. “Adırda kal, talaada kal!” “yok ol, kaybol!” anlamına gelen bir serzeniş. Adıra kal: Kazakça, mahrum ol, yoksun kal! demek. Karadeniz ve Doğu Anadolu’da “andıra kalsın, andır kalsın, ander kalsın!” diye aynı manada bir deyim vardır.",
