    "comment": "Binbir hile ile kapmış başköşeyi, hürmet umar, tilki\nBilmez, kurnaz diye tilkiye hürmet edilmez\nNihayet, bir geyiğe kalmış, arslana has mevkî,\nHeyhat, güzel diye geyiğe merhamet edilmez!",
