    "comment": "“Bir evde dü-zen olunca, o evde düzen olmaz.”\nIrk: Bir biri ile muhabbetli okmak, kavga döğüşü olmayan, yumuşak muamele.\nIrksız: Geçimsiz, kokmuş. (Kırgız Tilinin Sözdügü II, 828)",
