    "comment": "“Meşveretsiz yapılan işten hayır gelmez.”\n“Hırs, şükürsüzlük olduğu gibi sebebi mahrumiyettir.” (Nursi. 28. Mektup)\nOolukma: Kendi burnunun dikine gitme. Kendi dediğini, kendi bildiğini yapma. Eeelenüü. Eeenbaş. Oolukma kılat özündü, opsuz kılat sözündü: Bişey sanır kendini, kıymetsiz eder sözünü. (Şükürbekov)\nOolukkan at: Hızını almış, artık çatlayıncaya kadar durmayan at. (Kaynak: Nurlan Şerimbekov)\nEelikme: Arzusunu bir an evvel elde edeyim deme, sabırsızlanma, hırslanma.",
