    "comment": "“Yedisinde neyse yetmişinde de o.”\nKaltır: Kal kelimesi 4. manası, yok olma, ortadan kalma anlamına gelir. Bırak, kalsın. Kaltırdım: Bıraktım.",
    "letter": "O"
